package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.StartPaymentOrderEntryRequest;
import com.bank.payments.adapters.in.rest.StartPaymentOrderEntryResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.model.PaymentOrder;
import com.bank.payments.domain.port.AccountRepository;
import com.bank.payments.domain.port.MovementGateway;
import com.bank.payments.domain.port.OrderRepository;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Optional;

/**
 * Use case StartPaymentOrderEntry (legacy PAGOORD).
 * Without input data: paragraph 1000-PRIMERA-VEZ (MOVE 'WEB' TO CANALO).
 * With input data: paragraph 2000-PROCESAR (validate, read order, commission, debit, register payment).
 */
public class StartPaymentOrderEntryService {

    private static final BigDecimal LIMIT = new BigDecimal("50000");
    private static final BigDecimal COMMISSION_WEB = new BigDecimal("1.00");
    private static final BigDecimal COMMISSION_OTHER = new BigDecimal("2.50");
    private static final BigDecimal VALUE_MODULUS = new BigDecimal("1000000000");

    private final OrderRepository orderRepository;
    private final AccountRepository accountRepository;
    private final MovementGateway movementGateway;

    public StartPaymentOrderEntryService() {
        this(null, null, null);
    }

    public StartPaymentOrderEntryService(OrderRepository orderRepository,
                                         AccountRepository accountRepository,
                                         MovementGateway movementGateway) {
        this.orderRepository = orderRepository;
        this.accountRepository = accountRepository;
        this.movementGateway = movementGateway;
    }

    public StartPaymentOrderEntryResponse execute(StartPaymentOrderEntryRequest request) {
        if (isFirstEntry(request)) {
            return new StartPaymentOrderEntryResponse("WEB");
        }
        process(request);
        return new StartPaymentOrderEntryResponse(null);
    }

    private static boolean isFirstEntry(StartPaymentOrderEntryRequest r) {
        return r == null
                || (r.orderNumber() == null
                && r.companyId() == null
                && r.accountType() == null
                && r.accountNumber() == null
                && r.value() == null
                && r.channel() == null
                && r.approvalKey() == null);
    }

    private void process(StartPaymentOrderEntryRequest r) {
        // 2100-VALIDAR-ENTRADA
        validateInput(r);

        // 2200-LEER-ORDEN
        int orderNumber = toOrderNumber(r.orderNumber());
        Optional<PaymentOrder> found = orderRepository.findByKeyForUpdate(orderNumber, r.companyId());
        if (found.isEmpty()) {
            throw new BusinessError("ORDER_NOT_FOUND", "-1", "ORDEN NO EXISTE");
        }
        PaymentOrder order = found.get();
        if (!"P".equals(order.status())) {
            throw new BusinessError("ORDER_NOT_PENDING", "-1", "ORDEN NO ESTA PENDIENTE");
        }
        BigDecimal inputValue = r.value() == null ? BigDecimal.ZERO : r.value();
        BigDecimal wsValue = inputValue.setScale(2, RoundingMode.DOWN).remainder(VALUE_MODULUS);
        if (wsValue.compareTo(order.orderValue()) != 0) {
            throw new BusinessError("VALUE_MISMATCH", "-1", "VALOR NO COINCIDE CON LA ORDEN");
        }

        // 2300-CALCULAR-COMISION
        BigDecimal commission;
        if (order.orderValue().compareTo(LIMIT) >= 0) {
            commission = new BigDecimal("0.00");
        } else if ("WEB".equals(r.channel())) {
            commission = COMMISSION_WEB;
        } else {
            commission = COMMISSION_OTHER;
        }
        BigDecimal total = order.orderValue().add(commission);

        // 2400-DEBITAR-CUENTA (PAGODEB)
        String debResp = debit(r.accountNumber(), r.accountType(), total);
        switch (debResp) {
            case "00":
                break;
            case "10":
                throw new BusinessError("ACCOUNT_INACTIVE", "-1", "CUENTA INACTIVA");
            case "20":
                throw new BusinessError("INSUFFICIENT_BALANCE", "-1", "SALDO INSUFICIENTE");
            default:
                throw new BusinessError("INVALID_ACCOUNT", "-1", "CUENTA NO VALIDA");
        }

        // 2500-REGISTRAR-PAGO
        long movement = movementGateway.registerMovement(order.orderNumber());
        orderRepository.markPaid(order.orderNumber(), order.companyId(), movement, commission);
    }

    private void validateInput(StartPaymentOrderEntryRequest r) {
        if (!isNumeric(r.orderNumber()) || isAllZeros(r.orderNumber())) {
            throw new BusinessError("INVALID_ORDER_NUMBER", "-1", "NUMERO DE ORDEN INVALIDO");
        }
        String type = r.accountType();
        if (!"CTE".equals(type) && !"AHO".equals(type) && !"VIR".equals(type)) {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", "-1", "TIPO DE CUENTA NO PERMITIDO");
        }
        String channel = r.channel();
        if (!"WEB".equals(channel) && !"OFI".equals(channel)) {
            throw new BusinessError("CHANNEL_NOT_ALLOWED", "-1", "CANAL NO PERMITIDO");
        }
        if ("OFI".equals(channel) && isSpaces(r.approvalKey())) {
            throw new BusinessError("APPROVAL_KEY_REQUIRED", "-1", "CLAVE DE APROBACION REQUERIDA");
        }
    }

    private String debit(Long accountNumber, String type, BigDecimal amount) {
        Optional<Account> found = accountRepository.findByNumberForUpdate(accountNumber);
        if (found.isEmpty()) {
            return "30";
        }
        Account account = found.get();
        if (!account.accountType().equals(type)) {
            return "40";
        }
        if (!"A".equals(account.status())) {
            return "10";
        }
        if (account.balance().compareTo(amount) < 0) {
            return "20";
        }
        accountRepository.updateBalance(account.accountNumber(), account.balance().subtract(amount));
        return "00";
    }

    private static boolean isNumeric(String s) {
        if (s == null || s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static boolean isAllZeros(String s) {
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != '0') {
                return false;
            }
        }
        return true;
    }

    private static boolean isSpaces(String s) {
        if (s == null) {
            return true;
        }
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != ' ') {
                return false;
            }
        }
        return true;
    }

    private static int toOrderNumber(String s) {
        // MOVE ORDENI TO WS-CL-NUMERO PIC 9(7): keeps the low-order 7 digits
        String digits = s.length() > 7 ? s.substring(s.length() - 7) : s;
        return Integer.parseInt(digits);
    }
}
